using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEditor.Build.Reporting;
using QuietDread;

public static class BuildGame {
 [MenuItem("The Quiet Dread/Build Windows")]
 public static void Build(){
  var root=Path.GetFullPath(Path.Combine(Application.dataPath,".."));
  Directory.CreateDirectory(Path.Combine(root,"Build/Windows"));
  PlayerSettings.companyName="Quiet Dread Workshop";PlayerSettings.productName="The Quiet Dread";PlayerSettings.bundleVersion="0.12.0";
  PlayerSettings.defaultScreenWidth=1600;PlayerSettings.defaultScreenHeight=900;PlayerSettings.fullScreenMode=FullScreenMode.Windowed;PlayerSettings.resizableWindow=true;PlayerSettings.runInBackground=true;
  PlayerSettings.SetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Standalone,ScriptingImplementation.Mono2x);
  if(AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/Surface.mat")==null){var material=new Material(Shader.Find("Standard"));material.EnableKeyword("_EMISSION");material.SetColor("_EmissionColor",Color.gray);AssetDatabase.CreateAsset(material,"Assets/Resources/Surface.mat");}
  AssetDatabase.Refresh();if(AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/Canopy.mat")==null){var leaf=new Material(Shader.Find("Standard"));leaf.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Resources/TreeCanopy.png");leaf.SetFloat("_Mode",1);leaf.SetFloat("_Cutoff",.35f);leaf.SetFloat("_Glossiness",.05f);leaf.EnableKeyword("_ALPHATEST_ON");leaf.renderQueue=2450;AssetDatabase.CreateAsset(leaf,"Assets/Resources/Canopy.mat");}
  var canopy=AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/Canopy.mat");canopy.color=new Color(.55f,.62f,.45f);EditorUtility.SetDirty(canopy);AssetDatabase.SaveAssets();
  var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);EditorSceneManager.SaveScene(scene,"Assets/QuietDread.unity");
  AssetDatabase.Refresh();RulesChecks.Run(root);TerrainChecks.Run(root);CoherenceChecks.Run(root);BattlePolishChecks.Run(root);NarrativeChecks.Run(root);TrailChecks.Run(root);CommanderLegacyChecks.Run(root);MusicChecks.Run(root);
  var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/QuietDread.unity"},locationPathName=Path.Combine(root,"Build/Windows/The Quiet Dread.exe"),target=BuildTarget.StandaloneWindows64,options=BuildOptions.None});
  if(report.summary.result!=BuildResult.Succeeded)throw new Exception("Build failed: "+report.summary.result);
  File.WriteAllText(Path.Combine(root,"Documentation/BUILD-RESULT.txt"),"Unity "+Application.unityVersion+"\nWindows x64 native player\nResult: "+report.summary.result+"\nBytes: "+report.summary.totalSize+"\nTime: "+DateTime.Now.ToString("O"));
  Debug.Log("QUIET_DREAD_BUILD_SUCCESS "+report.summary.totalSize);
 }
}
public static class RulesChecks {
 static int checks;static List<string> report;
 static void Check(bool ok,string name){if(!ok)throw new Exception("CHECK FAILED: "+name);checks++;report.Add("PASS "+name);}
 public static void Run(string root){checks=0;report=new List<string>();var d=Content.Load();Check(d.factions.Length==17,"17 factions");Check(d.units.Length==243,"243 profiles");Check(d.units.Count(p=>p.titan)==17,"every faction has a titan");Check(d.units.Select(p=>p.id).Distinct().Count()==d.units.Length,"unique profile identifiers");
  foreach(var f in d.factions){Check(d.units.Any(p=>p.faction==f.id&&p.commander),f.name+" commanders");Check(Battle.Validate(d,f.id,f.defaults.ToList())==null,f.name+" legal recommended army");Check(d.units.Single(p=>p.faction==f.id&&p.titan).cost>=500,f.name+" titan cost");}
  var own=new List<string>{"marshal","clawrat","mortar","confessor","vermin_titan"};var b=Battle.Create(d,"vermin",own,"vault",new List<string>{"vault_titan","vault_0"},42);b.terrain=new int[Battle.W*Battle.H];b.Begin();Check(b.Living(0).Count(q=>q.spawned)==1,"All-Mother births a free brood at turn start");var queen=b.Living(0).First(u=>b.P(u).titan);for(int i=0;i<10;i++)b.Spawn(queen,"clawrat");Check(b.Living(0).Count(u=>u.spawned)<=6,"active brood cap and free-cell limit");
  var victim=b.Living(0).First(u=>u.spawned);b.Hurt(victim,999);Check(b.Spawn(queen,"clawrat"),"destroyed brood can be replaced without lifetime cap");
  var gun=b.Living(1).First(u=>b.P(u).titan);var infantry=b.Living(0).First(u=>u.type=="clawrat"&&!u.spawned);gun.x=12;gun.y=6;infantry.x=6;infantry.y=6;b.turn=1;Check(b.ShotError(gun,infantry)!=null,"siege engine must brace");b.Act(gun,"brace",gun.x,gun.y);Check(b.DamagePreview(gun,infantry)>=infantry.hp,"siege direct hit can kill a regiment");Check(b.Chance(gun,infantry)==55,"siege shot has limited accuracy");
  var caster=b.Living(0).First(u=>u.type=="confessor");caster.x=5;caster.y=6;b.turn=0;caster.ap=2;b.aether[0]=0;Check(!b.Act(caster,"lance",gun.x,gun.y),"magic cannot be cast without resource");b.aether[0]=6;gun.x=9;Check(b.Act(caster,"lance",gun.x,gun.y),"magic cast spends Aether");Check(b.aether[0]==3,"magic resource accounting");
  b.terrain[6*Battle.W+7]=1;Check(!b.LOS(5,6,9,6),"ruins block line of sight");b.terrain[6*Battle.W+7]=0;
  foreach(var f in d.factions){var types=new List<string>{f.id+"_titan",f.defaults[0],f.defaults[1]};var test=Battle.Create(d,f.id,types,"compact",new List<string>{"captain","rifles"},42);test.terrain=new int[Battle.W*Battle.H];test.Begin();var titan=test.Living(0).First(q=>test.P(q).titan);titan.x=5;titan.y=5;var friend=test.Living(0).First(q=>!test.P(q).titan);friend.x=5;friend.y=6;friend.hp=Math.Max(1,friend.hp-15);var hostile=test.Living(1).First();hostile.x=7;hostile.y=5;test.biomass[0]=3;titan.hp-=20;string ability=test.P(titan).ability;if(ability=="raise")test.Hurt(friend,999);int tx=ability=="veil"?6:hostile.x,ty=ability=="veil"?8:hostile.y;Check(test.Act(titan,"signature",tx,ty),f.name+" signature executes under valid conditions");Check(titan.ap<2,f.name+" signature consumes action points");}
  var coverTest=Battle.Create(d,"compact",new List<string>{"captain","rifles"},"vermin",new List<string>{"marshal","clawrat"},42);coverTest.terrain=new int[Battle.W*Battle.H];coverTest.Begin();var shooter=coverTest.Living(0).First();var covered=coverTest.Living(1).First();int openChance=coverTest.Chance(shooter,covered);coverTest.terrain[covered.y*Battle.W+covered.x]=2;Check(coverTest.Chance(shooter,covered)==openChance-20,"cover reduces firearm accuracy");Check(!coverTest.Act(shooter,"move",covered.x,covered.y),"occupied enemy cell cannot be entered");
  foreach(var f in d.factions){var roster=f.defaults.Take(6).ToList();roster.Add(f.id+"_titan");var foe=d.factions[(Array.IndexOf(d.factions,f)+1)%17];var er=foe.defaults.Take(6).ToList();er.Add(foe.id+"_titan");var sim=Battle.Create(d,f.id,roster,foe.id,er,123);sim.Begin();int steps=0;while(!sim.finished&&steps++<4000)sim.AI();Check(sim.finished,f.name+" AI battle terminates with titan");Check(sim.units.All(u=>u.hp>=0&&u.ap>=0),f.name+" simulation invariants");}
  foreach(string mode in new[]{"trail","conquest"}){var c=Campaign.Create(d,mode,"argent",d.F("argent").defaults.ToList());if(mode=="trail")c.Visit(c.nodes.First(c.Available));else c.Move(1);var fight=c.MakeBattle();Check(fight!=null,mode+" creates tactical battle");fight.Begin();fight.finished=true;fight.winner=0;Check(c.Settle(fight),mode+" settles victory");int gold=c.gold;Check(!c.Settle(fight)&&c.gold==gold,mode+" settlement is idempotent");if(mode=="trail"){c.Choice("gold");Check(c.row==0&&c.phase=="map","trail advances route after reward");}else{c.Capture(false);Check(c.provinces[1].owner=="argent","Conquest captures settlement");Check(c.EndTurn(),"Conquest advances economy and rivals");}
   var text=JsonUtility.ToJson(new SaveGame{campaign=c,battle=fight});var saved=JsonUtility.FromJson<SaveGame>(text);saved.campaign.data=d;saved.battle.data=d;Check(saved.campaign.gold==c.gold&&saved.battle.units.Count==fight.units.Count,mode+" save roundtrip");}
  var reordered=d.F("argent").defaults.ToList();string leader=reordered[0];reordered.RemoveAt(0);reordered.Add(leader);var lateCommander=Campaign.Create(d,"trail","argent",reordered);Check(lateCommander.Army.units.Any(u=>u.id==lateCommander.commanderId),"commander is retained even when last in muster order");
  var death=Campaign.Create(d,"trail","vermin",d.F("vermin").defaults.ToList());death.Visit(death.nodes.First(death.Available));var deathFight=death.MakeBattle();deathFight.Begin();deathFight.units.First(u=>u.persistentId==death.commanderId).hp=0;deathFight.finished=true;deathFight.winner=0;death.Settle(deathFight);Check(death.status=="lost","death of original commander ends trail even after tactical victory");
  var run=Campaign.Create(d,"trail","argent",d.F("argent").defaults.ToList());int transitions=0;while(run.status=="active"&&transitions++<100){if(run.phase=="map")run.Visit(run.nodes.First(run.Available));else if(run.phase=="battle"){var fight=run.MakeBattle();fight.Begin();fight.finished=true;fight.winner=0;run.Settle(fight);}else if(run.phase=="shop")run.Choice("leave");else if(run.phase=="event")run.Choice("safe");else run.Choice("heal");}Check(run.status=="won"&&run.act==3,"complete three-act campaign reaches victory");
  var defense=Campaign.Create(d,"conquest","argent",d.F("argent").defaults.ToList());defense.provinces[1].owner="argent";defense.gold=1000;defense.selectedProvince=0;Check(defense.RaiseArmy(leader),"a second expedition can be raised");defense.invasionQueue.Add(new Invasion{province=0,attacker="kiln"});defense.NextDefense();var invasion=defense.MakeBattle();Check(invasion.factions[1]=="kiln","defense uses the actual invading faction");foreach(var u in invasion.units.Where(u=>u.team==0))u.hp=0;invasion.deployment=false;invasion.finished=true;invasion.winner=1;defense.Settle(invasion);Check(defense.provinces[0].owner=="argent"&&defense.phase=="battle","second stationed army defends before province falls");var lastDefense=defense.MakeBattle();foreach(var u in lastDefense.units.Where(u=>u.team==0))u.hp=0;lastDefense.deployment=false;lastDefense.finished=true;lastDefense.winner=1;defense.Settle(lastDefense);Check(defense.provinces[0].owner=="kiln"&&defense.armies.Count==0,"province falls after all defending armies are defeated");defense.selectedProvince=1;Check(defense.Build("barracks"),"armyless campaign can build recovery barracks");Check(defense.RaiseArmy(leader),"armyless campaign can recover by raising an expedition");
  var siege=Campaign.Create(d,"conquest","argent",d.F("argent").defaults.ToList());siege.provinces[1].owner="kiln";siege.provinces[1].tier=3;Check(siege.Move(1,true)&&siege.phase=="siege","siege starts against developed enemy region");siege.ledgers.ForEach(l=>l.gold=-10000);siege.EndTurn();Check(siege.siegeTurns==1&&siege.phase=="siege","siege advances with strategic economy");siege.EndTurn();Check(siege.phase=="battle"&&siege.MakeBattle().Living(1).Count()<7,"two-turn siege produces weakened tactical defenders");
  var fort=Campaign.Create(d,"conquest","argent",d.F("argent").defaults.ToList());fort.provinces[0].buildings.Add("fort");fort.invasionQueue.Add(new Invasion{province=0,attacker="kiln"});fort.NextDefense();var fortified=fort.MakeBattle();Check(fortified.Living(0).All(u=>u.ward==6),"friendly fort shields defenders rather than strengthening invaders");
  coverTest.terrain=new int[Battle.W*Battle.H];shooter.x=5;shooter.y=5;covered.x=7;covered.y=5;int beforeMark=coverTest.Chance(shooter,covered);Check(coverTest.Act(shooter,"fire",covered.x,covered.y)&&covered.markedBy==0&&coverTest.Chance(shooter,covered)==beforeMark+10,"Compact hits coordinate subsequent allied fire");
  var memory=Battle.Create(d,"vermin",new List<string>{"marshal","clawrat","confessor","vermin_titan"},"compact",new List<string>{"captain"},42);memory.terrain=new int[Battle.W*Battle.H];memory.Begin();var marshal=memory.Living(0).First(u=>u.type=="marshal");var foeUnit=memory.Living(1).First();marshal.x=5;marshal.y=5;foeUnit.x=7;foeUnit.y=5;memory.memory[0]=1;Check(memory.Act(marshal,"memory",7,5)&&memory.memory[0]==0&&foeUnit.markedBy==0,"Memory resource exposes a target");memory.doctrine="brood";var fallenBrood=memory.units.First(u=>u.type=="clawrat"&&!u.spawned);memory.Hurt(fallenBrood,999);memory.biomass[0]=2;Check(memory.Act(marshal,"brood",5,5)&&fallenBrood.Alive&&fallenBrood.hp==memory.MaxHP(fallenBrood)/2,"Chitterhold restores fallen persistent brood at half strength");marshal.ap=2;memory.biomass[0]=2;memory.Hurt(fallenBrood,999);Check(!memory.Act(marshal,"brood",5,5),"Chitterhold restoration is once per battle");memory.doctrine="deep";var seer=memory.units.First(u=>u.type=="confessor");Check(memory.Act(seer,"tunnel",8,2)&&seer.ap==1,"Deepdelve grants one-AP tunnels to infantry");var mother=memory.units.First(u=>memory.P(u).titan);Check(!memory.Act(mother,"tunnel",8,9),"Deepdelve does not tunnel a titan");
  Directory.CreateDirectory(Path.Combine(root,"Documentation"));report.Insert(0,checks+" native C# checks passed; includes 17 full AI battles with titans and all 17 signature powers.");File.WriteAllLines(Path.Combine(root,"Documentation/TEST-RESULTS.txt"),report);Debug.Log("QUIET_DREAD_TESTS_PASS "+checks);
 }
}





